importScripts("<%= javascript_url("turbo-offline-umd.min") %>")

// Documents - top-level navigation requests only
// We need `cache: "no-cache"` here to work around
// an annoying Safari PWA bug that predates offline mode
TurboOffline.addRule({
  match: (request) => request.destination === "document",
  except: /\/(edit|pin|watch|new)$/,
  handler: TurboOffline.handlers.networkFirst({
    cacheName: "main",
    maxAge: 60 * 60 * 24 * 3,
    networkTimeout: 3,
    fetchOptions: { cache: "no-cache" },
    maxEntrySize: 1024 * 1024
  })
})

TurboOffline.addRule({
  match: /\/assets\/.+[-\.][0-9a-f]+\.(js|css|svg|png|jpg|webp|woff2?|ico)$/,
  handler: TurboOffline.handlers.cacheFirst({
    cacheName: "assets",
    maxAge: 60 * 60 * 24 * 7,
    maxEntrySize: 1024 * 1024
  })
})

TurboOffline.addRule({
  match: /\/(boards|cards|users)\//,
  except: /\/(edit|pin|watch|new)$/,
  handler: TurboOffline.handlers.networkFirst({
    cacheName: "main",
    maxAge: 60 * 60 * 24 * 3,
    networkTimeout: 2,
    maxEntrySize: 1024 * 1024
  })
})

TurboOffline.addRule({
  match: /\/rails\/active_storage\//,
  handler: TurboOffline.handlers.networkFirst({
    cacheName: "storage",
    maxAge: 60 * 60 * 24 * 7,
    networkTimeout: 2,
    maxEntrySize: 2 * 1024 * 1024, // 2MB covers about 95% of all Fizzy blobs
<% if ENV["SERVICE_WORKER_CORS_ENABLED"] != "false" -%>
    fetchOptions: { mode: "cors" },
<% end -%>
    maxEntries: 500
  })
})

// Everything else
TurboOffline.addRule({
  except: /\/(service-worker\.js|edit|pin|watch|new)$/,
  handler: TurboOffline.handlers.networkFirst({
    cacheName: "main",
    maxAge: 60 * 60 * 24,
    networkTimeout: 3,
    maxEntrySize: 1024 * 1024
  })
})

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim())
})

TurboOffline.start()
--- PWA tests ---
require "test_helper"

class PwaControllerTest < ActionDispatch::IntegrationTest
  setup do
    sign_in_as :david
  end

  test "service worker fetches storage with CORS mode by default" do
    untenanted { get "/service-worker.js" }

    assert_response :success
    assert_match 'fetchOptions: { mode: "cors" }', response.body
  end

  test "service worker omits CORS fetch mode when disabled" do
    switch_env "SERVICE_WORKER_CORS_ENABLED", "false" do
      untenanted { get "/service-worker.js" }
    end

    assert_response :success
    assert_no_match(/mode: "cors"/, response.body)
  end

  private
    def switch_env(key, value)
      old, ENV[key] = ENV[key], value
      yield
    ensure
      ENV[key] = old
    end
end
