Path('app/models/push_subscription.rb').write_text('''require "digest"
require "uri"

class PushSubscription < ApplicationRecord
  belongs_to :account, default: -> { user.account }
  belongs_to :user

  before_validation :set_endpoint_digest

  validates :endpoint, presence: true, length: { maximum: 4096 }
  validates :endpoint_digest, presence: true, uniqueness: { scope: :user_id }
  validates :p256dh_key, :auth_key, presence: true
  validate :endpoint_must_use_https

  class << self
    def configured?
      vapid_public_key.present? && ENV["VAPID_PRIVATE_KEY"].present?
    end

    def vapid_public_key
      ENV["VAPID_PUBLIC_KEY"].presence
    end

    def vapid_options
      {
        subject: ENV["BASE_URL"].presence || "mailto:#{ENV["MAILER_FROM_ADDRESS"].presence || "sender@example.com"}",
        public_key: vapid_public_key,
        private_key: ENV["VAPID_PRIVATE_KEY"]
      }
    end

    def digest(endpoint)
      Digest::SHA256.hexdigest(endpoint)
    end
  end

  def deliver(payload)
    WebPush.payload_send(
      endpoint: endpoint,
      p256dh: p256dh_key,
      auth: auth_key,
      message: payload.to_json,
      vapid: self.class.vapid_options,
      ttl: 1.day.to_i
    )
  rescue WebPush::ExpiredSubscription, WebPush::InvalidSubscription
    destroy
  end

  private
    def set_endpoint_digest
      self.endpoint_digest = self.class.digest(endpoint) if endpoint.present?
    end

    def endpoint_must_use_https
      if endpoint.present?
        uri = URI.parse(endpoint)
        errors.add(:endpoint, "must be a secure URL") unless uri.scheme == "https" && uri.host.present? && uri.userinfo.blank?
      end
    rescue URI::InvalidURIError
      errors.add(:endpoint, "must be a secure URL")
    end
end
''')

Path('app/jobs/notification/push_job.rb').write_text('''class Notification::PushJob < ApplicationJob
  include NotificationsHelper

  queue_as :backend

  retry_on WebPush::TooManyRequests, WebPush::PushServiceError, Net::OpenTimeout, Net::ReadTimeout,
    wait: :polynomially_longer, attempts: 5

  discard_on ActiveJob::DeserializationError

  def perform(notification, subscription)
    if PushSubscription.configured? && notification.unread? &&
        notification.user_id == subscription.user_id && notification.account.active? && subscription.user.active?
      subscription.deliver(push_payload(notification))
    end
  end

  private
    def push_payload(notification)
      source = notification.source
      title, body = case source
      when Mention
        [ mention_notification_title(source), mention_notification_body(source) ]
      when Event
        [ event_notification_title(source), event_notification_body(source) ]
      end

      {
        title: title,
        body: body,
        url: Rails.application.routes.url_helpers.card_path(notification.card, script_name: notification.account.slug),
        tag: notification.id
      }
    end
end
''')

